// Planeswalk emblem art (29 Oct 2026). Painted discs from Randall's art packs + gold medallion frame,
// and Slay the Spire-style key-word colouring for item text. Drop-in: load after the game script.
// PW_EMB_ART.html(key) returns the medallion markup to use instead of embSvg(key); PW_EMB_ART.kw(text) colours key words.
(()=>{const ART={"beacon": "data:image/webp;base64,", "contract": "data:image/webp;base64,", "crown": "data:image/webp;base64,", "dawn": "data:image/webp;base64,", "embers": "data:image/webp;base64,", "font": "data:image/webp;base64,", "furnace": "data:image/webp;base64,", "hearth": "data:image/webp;base64,", "horde": "data:image/webp;base64,", "lantern": "data:image/webp;base64,", "legion": "data:image/webp;base64,", "monument": "data:image/webp;base64,", "paradox": "data:image/webp;base64,", "pyre": "data:image/webp;base64,", "season": "data:image/webp;base64,", "signet": "data:image/webp;base64,", "spark": "data:image/webp;base64,", "surge": "data:image/webp;base64,", "twin": "data:image/webp;base64,"};
const ring={R:'#c8404f',W:'#f1e7cf'};
const studs={C:4,R:6,M:8,B:4};
const MANA={"W": "data:image/webp;base64,", "U": "data:image/webp;base64,", "B": "data:image/webp;base64,", "R": "data:image/webp;base64,", "G": "data:image/webp;base64,"},COLOR={signet:['W','B'],contract:['B']};
// a key with no EMB row or no painting never calls back into embSvg (it would loop forever); it gets the plain disc or a bare ring
function html(k){const d=EMB[k];if(!d||!ART[k])return d&&typeof embSvg0==='function'?embSvg0(k):'<svg class="emb" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="11" fill="#2a1a10" stroke="#e8b95b" stroke-width="1.4"/></svg>';const r=d.r||'C',inner=r==='B'?'#d65a6a':ring[d.col]||'#b8893a',n=studs[r]||4;
 let s='';for(let i=0;i<n;i++)s+=`<path transform="rotate(${i*360/n} 50 50)" d="M50 .8 L53.4 4.6 L50 8.4 L46.6 4.6Z" fill="url(#pwEmbGold)" stroke="#3a2208" stroke-width=".6"/>`;
 const cs=(COLOR[k]||(d.col?[d.col]:[])).filter(c=>MANA[c]);/* unknown colour letters (C, GW) draw no pip instead of throwing */const pip=cs.map((c,i)=>`<i class="emb-mana" style="background-image:url(&quot;${MANA[c].replace(/"/g,"%22")}&quot;);--i:${i}" aria-hidden="true"></i>`).join('');
 return `<span class="emb-art" data-k="${k}" data-r="${r}" role="img" aria-label="${d.name}" title="${d.name}: ${d.text.replace(/"/g,'&quot;')}"><img src="${ART[k]}" alt="" draggable="false"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="50" r="47" fill="none" stroke="url(#pwEmbGold)" stroke-width="4"/><circle cx="50" cy="50" r="43.2" fill="none" stroke="${inner}" stroke-opacity=".8" stroke-width="1.1"/><circle cx="50" cy="50" r="49.2" fill="none" stroke="#000" stroke-opacity=".55" stroke-width="1"/>${s}</svg>${pip}</span>`}
const KW=[[/\b(\d+%?|\+\d+\/\+\d+|twice|double)\b/g,'num'],[/\b(damage|deal(s)?|burn)\b/g,'dmg'],[/\b(heal(s)?|life)\b/g,'heal'],[/\b(energy)\b/g,'en'],[/\b(noncreature spell|instant or sorcery|Soldiers?|Goblins?|tokens?|flying|haste)\b/g,'kw']];
function kw(t){const parts=[];KW.forEach(([re,c])=>{t=t.replace(re,s=>{parts.push(`<i class="k ${c}">${s}</i>`);return `\u0001${parts.length-1}\u0002`})});return t.replace(/\u0001(\d+)\u0002/g,(_,i)=>parts[i])}
function defs(){if(document.getElementById('pwEmbDefs'))return;const d=document.createElement('div');d.innerHTML='<svg id="pwEmbDefs" width="0" height="0" style="position:absolute" aria-hidden="true"><defs><linearGradient id="pwEmbGold" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#fff1c4"/><stop offset=".35" stop-color="#e8b95b"/><stop offset=".7" stop-color="#8a5a1c"/><stop offset="1" stop-color="#f3d38a"/></linearGradient></defs></svg>';document.body.appendChild(d.firstChild)}
window.PW_EMB_ART={html,kw,defs,keys:Object.keys(ART)};})();

PW_EMB_ART.defs();
// the hero screen draws before this file loads; draw it again so its signature emblems get their discs
if(document.querySelector('.screen.heroes')&&typeof render==='function')try{render()}catch(e){}
